<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class RestaurantClaim extends Model {protected $guarded=[]; protected function casts():array{return ['submitted_at'=>'datetime','reviewed_at'=>'datetime','email_verified_at'=>'datetime','email_verification_expires_at'=>'datetime','activation_expires_at'=>'datetime','certified'=>'boolean'];} public function restaurant(){return $this->belongsTo(Restaurant::class);} public function user(){return $this->belongsTo(User::class);} public function reviewer(){return $this->belongsTo(User::class,'reviewed_by');} public function isFirstVerification():bool{return $this->source === 'first_claim';} }
